package com.cardcombat;import java.util.*;import org.bukkit.command.*;import org.bukkit.entity.Player;public final class MatchCommand implements CommandExecutor,TabCompleter{private final CardCombatPlugin p;public MatchCommand(CardCombatPlugin p){this.p=p;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player))return true;Player x=(Player)s;String sub=a.length==0?"status":a[0];if(sub.equalsIgnoreCase("queue"))p.matchmaking().join(x);else if(sub.equalsIgnoreCase("leave"))p.matchmaking().leave(x);else x.sendMessage("Queue: "+p.matchmaking().position(x.getUniqueId()));return true;}public List<String>onTabComplete(CommandSender s,Command c,String l,String[]a){return a.length==1?Arrays.asList("queue","leave","status"):Collections.emptyList();}}
